per_hop.query:
SELECT ?dateOfDeath ?teacher WHERE {
  ?arielRamirez a dbo:Person ;
                foaf:name "Ariel Ramírez"@en ;
                dbo:deathDate ?dateOfDeath ;
                dbo:teacher ?teacher .
  ?teacher dbo:taught ?martaLambertini .
  ?martaLambertini foaf:name "Marta Lambertini"@en .
} FILTER(?dateOfDeath = "2010-02-18"^^xsd:date)

SELECT ?album WHERE {
  ?album a dbo:Album ;
         dbo:artist dbr:Carlos_Santana ;
         dbo:albumType "studio" ;
         dbo:track ?track .
  ?track rdfs:label ?trackName .
  FILTER(CONTAINS(LCASE(?trackName), "stormy"))
} LIMIT 1

SELECT ?person WHERE {
  ?song wdt:P31 wd:Q134428;                       # instance of song
        rdfs:label "Rebuild"@en;
        wdt:P175 ?relientKVocalist, ?jonForeman.
  ?relientKVocalist wdt:P136 wd:Q184902;           # genre: Christian rock (attribute common for Relient K)
                     wdt:P106 wd:Q639669.          # occupation: musician
  ?jonForeman wdt:P31 wd:Q5;                       # human
              wdt:P106 wd:Q639669.                  # occupation: musician
  ?relientKVocalist wdt:P31 wd:Q5;                 # human
  ?georgeThorogood wdt:P31 wd:Q5;
                   rdfs:label "George Thorogood"@en;
                   wdt:P106 wd:Q639669.              # occupation: musician
  FILTER (?relientKVocalist != ?jonForeman)
}
LIMIT 1

